class Solution {
public:
    int maxProduct(string s){int n=s.size(),full=(1<<n)-1;
        vector<int>best(1<<n,0);
        for(int mask=1;mask<=full;++mask){string t;
            for(int i=0;i<n;++i)if(mask>>i&1)t+=s[i];
            string rev=t;reverse(rev.begin(),rev.end());
            if(t==rev)best[mask]=t.size();
        }
        for(int i=0;i<n;++i)for(int mask=0;mask<=full;++mask)
            if(mask>>i&1)best[mask]=max(best[mask],best[mask^(1<<i)]);
        int ans=0;for(int mask=0;mask<=full;++mask)
            ans=max(ans,best[mask]*best[full^mask]);
        return ans;
    }
};
